       background: linear-gradient(180deg, rgba(18, 26, 43, 0.95), rgba(12, 19, 33, 0.98));
       border: 1px solid var(--panel-border);
       border-radius: 24px;
       padding: 32px;
       box-shadow: var(--shadow);
       backdrop-filter: blur(10px);
     }

     .eyebrow {
       margin: 0 0 10px;
       color: var(--accent);
       font-size: 0.85rem;
       font-weight: 700;
       letter-spacing: 0.08em;
       text-transform: uppercase;
     }

     h1 {
       margin: 0 0 12px;
       font-size: clamp(2rem, 4vw, 2.75rem);
       line-height: 1.1;
     }

     .intro {
       margin: 0 0 28px;
       color: var(--muted);
       font-size: 1rem;
       line-height: 1.6;
     }

     form {
       display: grid;
       gap: 20px;
     }

     .form-field {
       display: grid;
       gap: 8px;
     }

     label {
       font-weight: 600;
     }

     .required-indicator {
       color: #9cc0ff;
     }

     input {
       width: 100%;
       border: 1px solid var(--panel-border);
       background: var(--field-bg);
       color: var(--text);
       border-radius: 14px;
       padding: 14px 16px;
       font: inherit;
       transition: border-color 0.2s ease, box-shadow 0.2s ease, transform 0.2s ease;
     }

     input::placeholder {
       color: #73809a;
     }

     input:hover {
       border-color: #35507d;
     }

     input:focus {
       outline: 2px solid transparent;
       border-color: var(--accent);
       box-shadow: 0 0 0 3px rgba(120, 169, 255, 0.28);
       transform: translateY(-1px);
     }

     input[aria-invalid="true"] {
       border-color: #ff6b6b;
       box-shadow: 0 0 0 3px rgba(255, 107, 107, 0.18);
     }

     .helper-text,
     .error-text,
     .status-message {
       font-size: 0.94rem;
       line-height: 1.5;
     }

     .helper-text {
       color: var(--muted);
     }

     .error-text {
       margin: 0;
       color: var(--error);
     }

     .error-text[hidden],
     .status-message[hidden] {
       display: none;
     }

     .actions {
       display: flex;
       align-items: center;
       gap: 14px;
       flex-wrap: wrap;
     }

     button {
       border: 0;
       border-radius: 999px;
       padding: 14px 22px;
       font: inherit;
       font-weight: 700;
       color: #08101d;
       background: linear-gradient(135deg, #8ab4ff, var(--accent-strong));
       cursor: pointer;
       transition: transform 0.2s ease, box-shadow 0.2s ease, filter 0.2s ease;
       box-shadow: 0 14px 30px rgba(79, 140, 255, 0.28);
     }

     button:hover {
       filter: brightness(1.05);
       transform: translateY(-1px);
     }

     button:focus-visible {
       outline: 3px solid rgba(232, 237, 247, 0.9);
       outline-offset: 3px;
     }

     .status-message {
       margin: 0;
       color: var(--success);
       min-height: 1.5em;
     }

     @media (max-width: 600px) {
       .card {
         padding: 24px;
         border-radius: 20px;
       }
     }

     @media (forced-colors: active) {
       body {
         background: Canvas;
       }

       .card,
       input,
       button {
         border: 1px solid ButtonText;
         box-shadow: none;
       }

       .card {
         background: Canvas;
       }

       input,
       button {
         background: Canvas;
         color: CanvasText;
       }

       .skip-link,
       .helper-text,
       .error-text,
       .status-message,
       .intro {
         color: CanvasText;
       }
     }
   </style>
 </head>
 <body>
   <a class="skip-link" href="#main-content">Skip to main content</a>
   <main id="main-content">
     <section class="card" aria-labelledby="support-heading">
       <p class="eyebrow">Support</p>
       <h1 id="support-heading">Contact our support team</h1>
       <p class="intro">
         Share your details and we&apos;ll follow up as soon as possible.
       </p>

       <form id="support-form" novalidate>
         <div class="form-field">
           <label for="full-name">Full name <span class="required-indicator" aria-hidden="true">*</span></label>
           <input
             id="full-name"
             name="fullName"
             type="text"
             autocomplete="name"
             required
             aria-required="true"
             aria-describedby="full-name-error"
             placeholder="Jordan Lee"
           >
           <p id="full-name-error" class="error-text" hidden></p>
         </div>

         <div class="form-field">
           <label for="email-address">Email address <span class="required-indicator" aria-hidden="true">*</span></label>
           <input
             id="email-address"
             name="email"
             type="email"
             autocomplete="email"
             required
             aria-required="true"
             aria-describedby="email-address-error"
             placeholder="jordan@example.com"
           >
           <p id="email-address-error" class="error-text" hidden></p>
         </div>

         <div class="form-field">
           <label for="phone-number">Phone number</label>
           <input
             id="phone-number"
             name="phone"
             type="tel"
             autocomplete="tel"
             inputmode="tel"
             aria-describedby="phone-number-help phone-number-error"
             placeholder="(555) 123-4567"
           >
           <p id="phone-number-help" class="helper-text">
             Optional. Use a format like (555) 123-4567 or +1 555 123 4567.
           </p>
           <p id="phone-number-error" class="error-text" hidden></p>
         </div>

         <div class="actions">
           <button type="submit">Submit request</button>
           <p id="form-status" class="status-message" aria-live="polite" hidden></p>
         </div>
       </form>
     </section>
   </main>

   <script>
     const form = document.getElementById("support-form");
     const statusMessage = document.getElementById("form-status");
     const fieldConfigs = [
       {
         input: document.getElementById("full-name"),
         error: document.getElementById("full-name-error"),
         validate(value) {
           return value.trim() ? "" : "Enter your full name.";
         }
       },
       {
         input: document.getElementById("email-address"),
         error: document.getElementById("email-address-error"),
         validate(value) {
           const trimmedValue = value.trim();
           if (!trimmedValue) {
             return "Enter your email address.";
           }

           const emailPattern = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
           return emailPattern.test(trimmedValue) ? "" : "Enter a valid email address.";
         }
       },
       {
         input: document.getElementById("phone-number"),
         error: document.getElementById("phone-number-error"),
         validate(value) {
           const trimmedValue = value.trim();
           if (!trimmedValue) {
             return "";
           }

           const phonePattern = /^[+]?[0-9()\s-]{7,20}$/;
           return phonePattern.test(trimmedValue)
             ? ""
             : "Use digits, spaces, parentheses, or hyphens only.";
         }
       }
     ];

     function setFieldError(fieldConfig, message) {
       const isInvalid = Boolean(message);
       fieldConfig.input.setAttribute("aria-invalid", String(isInvalid));
       fieldConfig.error.textContent = message;
       fieldConfig.error.hidden = !isInvalid;
     }

     fieldConfigs.forEach((fieldConfig) => {
       fieldConfig.input.addEventListener("input", () => {
         if (fieldConfig.error.hidden) {
           return;
         }

         const message = fieldConfig.validate(fieldConfig.input.value);
         setFieldError(fieldConfig, message);
       });
     });

     form.addEventListener("submit", (event) => {
       event.preventDefault();
       statusMessage.hidden = true;
       statusMessage.textContent = "";

       let firstInvalidInput = null;

       fieldConfigs.forEach((fieldConfig) => {
         const message = fieldConfig.validate(fieldConfig.input.value);
         setFieldError(fieldConfig, message);

         if (!firstInvalidInput && message) {
           firstInvalidInput = fieldConfig.input;
         }
       });

       if (firstInvalidInput) {
         firstInvalidInput.focus();
         return;
       }

       statusMessage.textContent = "Thanks. Your support request is ready to send.";
       statusMessage.hidden = false;
       form.reset();

       fieldConfigs.forEach((fieldConfig) => {
         setFieldError(fieldConfig, "");
       });
     });
   </script>
 </body>
 </html>

')
